import { readFileSync, writeFileSync } from 'node:fs';

/**
 * Generates src/core/livedata/runtime.generated.ts from the plain-JS runtime source so that every
 * toolchain (Vite, Vitest, tsx) can import it without bundler-specific "?raw" imports.
 * A unit test fails when the generated file drifts from runtime.src.js.
 */
export function generatedRuntimeModule(source: string): string {
  return `// GENERATED by scripts/make-runtime.ts from runtime.src.js. Do not edit; run \`npm run runtime\`.\nexport const RUNTIME_SOURCE_RAW: string = ${JSON.stringify(source)};\n`;
}

if (process.argv[1]?.endsWith('make-runtime.ts')) {
  const source = readFileSync('src/core/livedata/runtime.src.js', 'utf8').replace(/\r\n/g, '\n');
  writeFileSync('src/core/livedata/runtime.generated.ts', generatedRuntimeModule(source));
  console.log('wrote src/core/livedata/runtime.generated.ts');
}
